export function create({ THREE, params, rng }) {
  const r = params.radius;
  const g = new THREE.Group();
  g.position.set(params.at[0], params.at[1], params.at[2]);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.08, r * 0.1, r * 1.2, 16), new THREE.MeshStandardMaterial({ color: 0x777777, metalness: 0.9, roughness: 0.35 }));
  post.position.y = r * 0.6;
  const head = new THREE.Group();
  head.position.y = r * 2.2;
  const rim = new THREE.Mesh(new THREE.TorusGeometry(r, r * 0.09, 16, 64), new THREE.MeshStandardMaterial({ color: 0x9a9a9a, metalness: 0.95, roughness: 0.25 }));
  const face = new THREE.Mesh(new THREE.CircleGeometry(r, 64), new THREE.MeshStandardMaterial({ color: 0xf4f1ea, roughness: 0.6 }));
  const danger = new THREE.Mesh(new THREE.RingGeometry(r * 0.68, r * 0.9, 32, 1, 0, Math.PI / 3),
    new THREE.MeshStandardMaterial({ color: 0xe74c3c, emissive: 0xe74c3c, emissiveIntensity: 0.4 }));
  danger.position.z = 0.002;
  const needle = new THREE.Mesh(new THREE.BoxGeometry(r * 0.85, r * 0.07, 0.01), new THREE.MeshStandardMaterial({ color: 0x111111 }));
  needle.geometry.translate(r * 0.42, 0, 0.006);
  head.add(rim, face, danger, needle);
  g.add(post, head);
  const shake = 0.02 + rng() * 0.02;
  return {
    object: g,
    update(t) {
      const rise = Math.min(1, t / (params.seconds || 2.5));
      const k = params.mode === "drop" ? 0.95 * (1 - rise) : params.mode === "high" ? 0.86 + 0.06 * Math.sin(t * 3) : 0.95 * rise;
      needle.rotation.z = Math.PI * (1 - k) + Math.sin(t * 27) * shake * k;
      danger.material.emissiveIntensity = 0.3 + 1.6 * k * (0.6 + 0.4 * Math.sin(t * 12));
    },
  };
}

