export function create({ THREE, params, rng }) {
  const g = new THREE.Group();
  const puffs = [];
  for (let i = 0; i < 90; i++) {
    const m = new THREE.Mesh(new THREE.SphereGeometry(1, 12, 10), new THREE.MeshStandardMaterial({ color: 0xffffff, transparent: true, roughness: 1, depthWrite: false }));
    puffs.push({ m, a: rng() * Math.PI * 2, up: 0.6 + rng() * 1.6, out: 0.2 + rng() * 1.0, size: 0.04 + rng() * 0.08, phase: rng(), life: 0.9 + rng() * 0.8 });
    g.add(m);
  }
  g.position.set(params.at[0], params.at[1], params.at[2]);
  const burst = params.burst !== false;
  return {
    object: g,
    update(t) {
      for (const p of puffs) {
        // the first wave bursts out at once; after it, puffs keep billowing in a loop
        const a = burst && t < p.life ? t : (t / p.life + p.phase) % 1 * p.life;
        const k = a / p.life, e = 1 - Math.exp(-a * 3);
        p.m.position.set(Math.cos(p.a) * p.out * e * (params.spread || 1), p.up * e * (params.height || 1), Math.sin(p.a) * p.out * e * (params.spread || 1));
        p.m.scale.setScalar(p.size * (1 + a * 4));
        p.m.material.opacity = Math.max(0, 0.8 * (1 - k));
      }
    },
  };
}
